import{_ as n,o as s,c as t,a4 as e}from"./chunks/framework.B-wJupoK.js";const o="/assets/image-20260506170830493.Nq4u0uRa.png",r="/assets/image-20260506170947308.YUjhgN3I.png",p="/assets/image-20260506172640597.CxnJCBQd.png",i="/assets/image-20260506172653937.D4bsjplR.png",l="/assets/image-20260506172809676.BUORGSW0.png",m="/assets/image-20260506171201989.BTedjLv2.png",g="/assets/image-20260506171254434.LuDAjiiY.png",c="/assets/image-20260506171344830.GGMV5aCk.png",_="/assets/image-20260506172602587.B3sfWH55.png",d="/assets/%E5%BE%AE%E4%BF%A1%E5%8F%B7%E5%92%8C%E4%BA%8C%E7%BB%B4%E7%A0%81.KtucpRsB.jpg",b="/assets/image-20260506171849746.DZJgeWZQ.png",h="/assets/image-20260506172925464.BPBe5mNM.png",E=JSON.parse('{"title":"万少的HarmonyOS知识库更新了","description":"","frontmatter":{},"headers":[],"relativePath":"鸿蒙开发技巧/万少的HarmonyOS知识库更新了/万少的HarmonyOS知识库更新了.md","filePath":"鸿蒙开发技巧/万少的HarmonyOS知识库更新了/万少的HarmonyOS知识库更新了.md","lastUpdated":1778061314000,"__rawMarkdown":"# 万少的HarmonyOS知识库更新了\\n\\n> 万少：华为HDE、鸿蒙极客\\n>\\n> 个人主页：https://blog.zbztb.cn/\\n>\\n> **2025年参与孵化了20+鸿蒙应用、技术文章300+、鸿蒙知识库用户500+、鸿蒙免费课程2套。**\\n>\\n> 如果你也喜欢交流AI和鸿蒙技术，欢迎扣我。\\n\\n## 前言\\n\\n![](assets/image-20260506170830493.png)\\n\\n​\\t这次知识库的更新对标 HarmonyOS官网 6.1.0（23）Release版本。总共更新了**13318**个文件。\\n\\n![](assets/image-20260506170947308.png)\\n\\n我为什么一直坚持使用ima内的HarmonyOS知识库，主要原因无他：**方便；**\\n\\n1. 你可以直接在微信的小程序中使用\\n\\n2. 也可以下载单独的客户端在电脑上使用\\n\\n3. 目前的知识库还支持接入腾讯系的**龙虾** **QCLAW**，里面让你的龙虾具有无限数据的能力；\\n\\n   ![](assets/image-20260506172640597.png)\\n\\n   ![](assets/image-20260506172653937.png)\\n\\n   4. 最近的ima也支持了copilot能力（需要申请），它可以让你的数据**活起来**\\n\\n      ![](assets/image-20260506172809676.png)\\n\\n   ---\\n\\n   \\n\\n使用自然语言获取相关的鸿蒙信息后，也可以提取成md文档，然后喂给你的AI编程工具使用。\\n\\n这就是知识库得到很多人喜欢使用的原因；\\n\\n![](assets/image-20260506171201989.png)\\n\\n\\n\\n![](assets/image-20260506171254434.png)\\n\\n\\n\\n## 如何使用\\n\\n1. 打开链接\\n\\n   > 【ima知识库】鸿蒙应用知识库HarmonyOS6 https://ima.qq.com/wiki/?shareId=b0d462ae618a0fefb5b714565cad3dd4a60411a435d5f81db51670ffb2ff3ad7\\n\\n2. 微信扫码\\n\\n   > ![](assets/image-20260506171344830.png)\\n\\n\\n3. 使用自然语言进行对话\\n\\n   ![](assets/image-20260506172602587.png)\\n\\n   \\n\\n\\n\\n## 关于我 \\n\\n我建立了一个鸿蒙技术开发交流群，已经满200人了，欢迎进群进行技术沟通；\\n\\n![](assets/%E5%BE%AE%E4%BF%A1%E5%8F%B7%E5%92%8C%E4%BA%8C%E7%BB%B4%E7%A0%81.jpg)\\n\\n\\n\\n## 另外\\n\\n目前开发鸿蒙技术，也是需要结合AI来提效，万少也专门录制一套**AI提效鸿蒙开发课**，有需要的小伙伴可以购买订阅，享受万少的1对1AI提效鸿蒙辅导；\\n\\n课程包含5个多小时的AI+鸿蒙能力；\\n\\n包括使用Trae 、智能体、rules、skill等常用的AI技巧；\\n\\n包括HarmonyOS的自动化语法检测，让你一次对话，就能生成正确的代码，杜绝语法幻觉；\\n\\n结合智谱AI能力，批量0成本生成图片素材、视频素材。\\n\\n> https://www.bilibili.com/cheese/play/ss832248878\\n\\n![](assets/image-20260506171849746.png)\\n\\n![](assets/image-20260506172925464.png)"}'),f={name:"鸿蒙开发技巧/万少的HarmonyOS知识库更新了/万少的HarmonyOS知识库更新了.md"};function A(u,a,k,q,S,y){return s(),t("div",null,[...a[0]||(a[0]=[e("",26)])])}const H=n(f,[["render",A]]);export{E as __pageData,H as default};
